1	//! A warm checker that answers for the components a session asks about, one request at a time.
2	//!
3	//! The one-shot [`crate::resolve`] roots a single program at every component's file. A Storybook session asks about
4	//! one component per story, so this keeps one checker warm, starts it on the first request, and roots a small program at
5	//! just the requested files: the checker loads what those files import, not the project.
6	//!
7	//! The snapshot of that program is kept between requests (ADR 0026 S6). The warm-up ([`OnDemand::warm_up`]) builds the
8	//! first: a program over the project's dependencies, so the first request re-roots it at its files and reads only what
9	//! they add, instead of reading the lib and every dependency's declarations from the disk while someone waits. The next request brings it up to date with
10	//! `updateSnapshot`, which re-reads only the files the session announced as changed ([`SemanticProvider::changed`]) and
11	//! keeps the rest as parsed, re-rooting the program when the request names other files. The checker does not see an
12	//! edit it is not told about, so before an answer every file the program read is compared with the stamp it had when
13	//! read ([`crate::stamps`]): one that changed unannounced makes the answer come from a fresh snapshot, with a warning
14	//! that names it.
15	//!
16	//! The worker runs on its own thread with its own runtime, so a caller on any thread (a NAPI worker, a rayon task)
17	//! never nests runtimes and can bound how long it waits. It converts an answer on the checker's thread
18	//! ([`crate::checker::Client::run_on_thread`]), where each of its requests is answered in place instead of crossing a
19	//! channel there and back; each request is still bounded by [`OnDemandConfig::request_timeout`]. A failure to start or a crash yields an outcome with no
20	//! components and one diagnostic, never an error; after [`MAX_RESTARTS`] crashes the checker stays down. A panic in
21	//! the checker counts as a crash: its session is not asked again, and a fresh one starts.
22	//!
23	//! What the checker holds is bounded by [`OnDemandConfig::max_rss_mib`] ([`Backend::memory_mib`]). Its memory is read
24	//! from its arenas, which leave out the host's (Node, Storybook), and it is never replaced: a closed session gives back
25	//! only part of its arenas, and a fresh one parses every file again, so a replacement raises what this process holds
26	//! (measured in `docs/gate-measurements.md`). Past the bound it stays down instead, and its components keep their
27	//! structural answer with a warning that says why.
28	//!
29	//! Requests wait in two queues: an interactive one (a story someone opened) is answered before any background one (a
30	//! warm-up, a fill, a prefetch), first come first served within each, and a background request a caller raised while
31	//! it waited moves to the interactive queue. So that background work is never starved, after [`INTERACTIVE_STREAK`]
32	//! interactive answers in a row while background requests wait, the oldest of them goes next.
33	
34	use std::collections::{BTreeSet, VecDeque};
35	use std::sync::atomic::{AtomicU32, Ordering};
36	use std::sync::{Arc, mpsc};
37	use std::thread::JoinHandle;
38	use std::time::{Duration, SystemTime};
39	
40	use caliper_docgen_core::types::semantic::{
41	    Delivery, Priority, SemanticOutcome, SemanticProvider, SemanticTarget, SharedPriority, SourceChange,
42	};
43	use caliper_docgen_core::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
44	use camino::{Utf8Path, Utf8PathBuf};
45	use rustc_hash::{FxHashMap, FxHashSet};
46	use tokio::sync::mpsc::error::TryRecvError;
47	use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender, unbounded_channel};
48	
49	use crate::checker::{Backend, Client};
50	use crate::rpc::{CallError, Rpc};
51	use crate::stamps::{self, Stamp};
52	use crate::{SemanticRequest, answer_on, group_by_file, root_files};
53	
54	/// The file a warm-up snapshot's program is rooted at, in the project's root: held in the checker's memory, never
55	/// written to disk ([`warm_source`]).
56	const WARM_FILE: &str = "__caliper_warm_up__.ts";
57	
58	/// How many files an unannounced-edit warning names before it counts the rest.
59	const UNTOLD_NAMED: usize = 5;
60	
61	/// Interactive answers in a row the checker gives while background requests wait, before the oldest background request
62	/// goes next: once first in its queue, a background request waits behind at most this many interactive ones.
63	const INTERACTIVE_STREAK: u32 = 4;
64	
65	/// Crashes the checker may have before it stays down for the session.
66	const MAX_RESTARTS: u32 = 3;
67	
68	/// What the checker may hold, in MiB, between requests, measured by its arenas: past it, it stops for the session. Its
69	/// arenas reached 46 MiB over 2,000 Chakra edits and 165 MiB over 937 Chakra and MUI components (single-component
70	/// programs peaked at 157 to 612 MiB in a `tsc` process); past this, it has loaded more than a story session needs.
71	const DEFAULT_MAX_RSS_MIB: u64 = 768;
72	
73	/// How many requests pass between memory checks: each reads the arenas' pages, which costs a few milliseconds. The
74	/// checker is also checked after its first program.
75	const RSS_CHECK_EVERY: u32 = 4;
76	
77	/// How long dropping a checker waits, by default, for its worker to finish a request and stop the checker, before leaving
78	/// the worker to finish on its own. Closing a session must not wait for a 60 s request.
79	const DEFAULT_SHUTDOWN_WAIT: Duration = Duration::from_secs(5);
80	
81	/// How a warm [`OnDemand`] checker starts and is kept: where it runs, how long to wait on it, and what it may hold.
82	#[derive(Debug, Clone)]
83	pub struct OnDemandConfig {
84	    /// Where the checker finds `node_modules`: its working directory.
85	    pub project_root: Utf8PathBuf,
86	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
87	    pub tsconfig: Option<Utf8PathBuf>,
88	    /// Bound on each request to the checker.
89	    pub request_timeout: Duration,
90	    /// What the checker may hold, in MiB, read after a request from its arenas (the part of this process's memory the
91	    /// `tsrs` crates allocated): past it, the checker stops for the session, its components keeping their structural
92	    /// answer with a warning. A request that needs more finishes first: the bound is between requests, not inside one.
93	    pub max_rss_mib: u64,
94	    /// How long dropping the checker waits for a request in progress before it lets the worker finish alone, and how
95	    /// long a checker that panicked or went past its memory bound is given to close its session.
96	    pub shutdown_wait: Duration,
97	}
98	
99	impl OnDemandConfig {
100	    /// A configuration for `project_root` with a 60 second request timeout, a 768 MiB memory bound, a 5 second shutdown
101	    /// wait, and no explicit tsconfig.
102	    pub fn new(project_root: Utf8PathBuf) -> Self {
103	        Self {
104	            project_root,
105	            tsconfig: None,
106	            request_timeout: Duration::from_secs(60),
107	            max_rss_mib: DEFAULT_MAX_RSS_MIB,
108	            shutdown_wait: DEFAULT_SHUTDOWN_WAIT,
109	        }
110	    }
111	}
112	
113	/// How the snapshots a warm checker answered from were made.
114	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
115	pub struct Snapshots {
116	    /// Built from the disk with `createSnapshot`: the warm-up's, the first request of a checker that was not warmed up,
117	    /// one after a file changed that the checker was not told about, or one after a snapshot could not be listed or
118	    /// updated.
119	    pub created: u32,
120	    /// Brought up to date from the one before with `updateSnapshot`: announced edits re-read, the rest kept.
121	    pub updated: u32,
122	}
123	
124	/// What the worker thread reports about the checker, for the type that owns the thread to read.
125	#[derive(Default)]
126	struct Gauges {
127	    created: AtomicU32,
128	    updated: AtomicU32,
129	}
130	
131	enum Job {
132	    /// Start the checker now instead of at the first request.
133	    Warm,
134	    /// Files changed on disk; queued before any request that may read them.
135	    Changed(SourceChange),
136	    Answer(Asked),
137	    /// Tests only: the worker waits until this is released (or its sender dropped) before it takes another job, so a
138	    /// test can queue requests while the worker is busy and know they are all filed before one is picked.
139	    #[cfg(test)]
140	    Hold(mpsc::Receiver<()>),
141	}
142	
143	/// One request waiting for the checker.
144	struct Asked {
145	    targets: Vec<SemanticTarget>,
146	    priority: SharedPriority,
147	    delivery: Delivery,
148	}
149	
150	/// The requests waiting for the checker, in two queues by priority, first in first out within each. A request is
151	/// filed by its priority when it arrives and moved to the interactive queue when a caller raised it while it waited.
152	/// After [`INTERACTIVE_STREAK`] interactive requests in a row while the background queue is not empty, the next is
153	/// the oldest background request.
154	struct Queue<T> {
155	    interactive: VecDeque<(T, SharedPriority)>,
156	    background: VecDeque<(T, SharedPriority)>,
157	    /// Interactive requests taken in a row while a background one waited.
158	    streak: u32,
159	}
160	
161	impl<T> Default for Queue<T> {
162	    fn default() -> Self {
163	        Self { interactive: VecDeque::new(), background: VecDeque::new(), streak: 0 }
164	    }
165	}
166	
167	impl<T> Queue<T> {
168	    fn push(&mut self, item: T, priority: SharedPriority) {
169	        match priority.get() {
170	            Priority::Interactive => self.interactive.push_back((item, priority)),
171	            Priority::Background => self.background.push_back((item, priority)),
172	        }
173	    }
174	
175	    fn is_empty(&self) -> bool {
176	        self.interactive.is_empty() && self.background.is_empty()
177	    }
178	
179	    /// The request the checker answers next.
180	    fn next(&mut self) -> Option<T> {
181	        let (raised, waiting): (VecDeque<_>, VecDeque<_>) = std::mem::take(&mut self.background)
182	            .into_iter()
183	            .partition(|(_, priority)| priority.get() == Priority::Interactive);
184	        self.interactive.extend(raised);
185	        self.background = waiting;
186	        let starving = self.streak >= INTERACTIVE_STREAK;
187	        let (next, streak) = match (self.interactive.pop_front(), self.background.is_empty()) {
188	            (Some(interactive), true) => (Some(interactive), 0),
189	            (Some(interactive), false) if !starving => (Some(interactive), self.streak + 1),
190	            (Some(interactive), false) => {
191	                self.interactive.push_front(interactive);
192	                (self.background.pop_front(), 0)
193	            }
194	            (None, _) => (self.background.pop_front(), 0),
195	        };
196	        self.streak = streak;
197	        next.map(|(item, _)| item)
198	    }
199	}
200	
201	/// A warm checker that answers for the components it is asked about. Dropping it stops the checker.
202	pub struct OnDemand {
203	    jobs: Option<UnboundedSender<Job>>,
204	    thread: Option<JoinHandle<()>>,
205	    /// Receives once when the worker has stopped the checker and is about to exit.
206	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
207	    shutdown_wait: Duration,
208	    gauges: Arc<Gauges>,
209	}
210	
211	impl OnDemand {
212	    /// Starts the worker thread. The checker itself starts on the first request, or on [`OnDemand::warm_up`].
213	    pub fn new(config: OnDemandConfig) -> Self {
214	        let shutdown_wait = config.shutdown_wait;
215	        let (jobs, queue) = unbounded_channel();
216	        let (stopped_tx, stopped) = mpsc::channel();
217	        let gauges = Arc::new(Gauges::default());
218	        let worker_gauges = Arc::clone(&gauges);
219	        let thread = std::thread::Builder::new()
220	            .name("caliper-tsc".to_string())
221	            .spawn(move || {
222	                worker(config, queue, worker_gauges);
223	                stopped_tx.send(()).ok();
224	            })
225	            .ok();
226	        Self {
227	            jobs: thread.as_ref().map(|_| jobs),
228	            thread,
229	            stopped: std::sync::Mutex::new(Some(stopped)),
230	            shutdown_wait,
231	            gauges,
232	        }
233	    }
234	
235	    /// How many snapshots the answers so far came from, by how each was made.
236	    pub fn snapshots(&self) -> Snapshots {
237	        Snapshots {
238	            created: self.gauges.created.load(Ordering::Relaxed),
239	            updated: self.gauges.updated.load(Ordering::Relaxed),
240	        }
241	    }
242	
243	    /// Starts the checker in the background, and builds the snapshot the first request starts from, so the first request
244	    /// pays for neither: a program over the project's dependencies (the packages its nearest `package.json` lists under
245	    /// `dependencies` and `peerDependencies`, and the lib), which the first request re-roots at its files.
246	    pub fn warm_up(&self) {
247	        if let Some(jobs) = &self.jobs {
248	            jobs.send(Job::Warm).ok();
249	        }
250	    }
251	
252	    /// Tests only: holds the worker at its next job until the returned sender sends or is dropped (see [`Job::Hold`]).
253	    #[cfg(test)]
254	    fn hold(&self) -> mpsc::Sender<()> {
255	        let (release, held) = mpsc::channel();
256	        if let Some(jobs) = &self.jobs {
257	            jobs.send(Job::Hold(held)).ok();
258	        }
259	        release
260	    }
261	}
262	
263	impl SemanticProvider for OnDemand {
264	    fn request(&self, targets: Vec<SemanticTarget>) -> mpsc::Receiver<SemanticOutcome> {
265	        let (reply, receiver) = mpsc::sync_channel(1);
266	        let delivery = Delivery::new(move |outcome| {
267	            // `None` drops the sender, which the receiver reads as a checker that stopped without answering.
268	            if let Some(outcome) = outcome {
269	                reply.send(outcome).ok();
270	            }
271	        });
272	        self.request_at(targets, SharedPriority::new(Priority::Interactive), delivery);
273	        receiver
274	    }
275	
276	    fn request_at(&self, targets: Vec<SemanticTarget>, priority: SharedPriority, delivery: Delivery) {
277	        match &self.jobs {
278	            Some(jobs) => {
279	                if let Err(refused) = jobs.send(Job::Answer(Asked { targets, priority, delivery }))
280	                    && let Job::Answer(asked) = refused.0
281	                {
282	                    asked.delivery.deliver(Some(SemanticOutcome::unavailable("the checker thread has stopped")));
283	                }
284	            }
285	            None => delivery.deliver(Some(SemanticOutcome::unavailable("could not start the checker thread"))),
286	        }
287	    }
288	
289	    fn changed(&self, change: SourceChange) {
290	        if let Some(jobs) = &self.jobs {
291	            jobs.send(Job::Changed(change)).ok();
292	        }
293	    }
294	}
295	
296	impl Drop for OnDemand {
297	    fn drop(&mut self) {
298	        // Closing the queue ends the worker loop, which stops the checker before the thread exits. A worker still inside
299	        // a long request is left to finish it: the checker stops when it does, or with this process.
300	        self.jobs.take();
301	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
302	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
303	        if let Some(thread) = self.thread.take()
304	            && stopped
305	        {
306	            thread.join().ok();
307	        }
308	    }
309	}
310	
311	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>, gauges: Arc<Gauges>) {
312	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
313	        Ok(runtime) => runtime,
314	        Err(error) => {
315	            let reason = format!("could not start an async runtime: {error}");
316	            while let Some(job) = queue.blocking_recv() {
317	                match job {
318	                    Job::Answer(asked) => asked.delivery.deliver(Some(SemanticOutcome::unavailable(reason.clone()))),
319	                    Job::Warm | Job::Changed(_) => {}
320	                    #[cfg(test)]
321	                    Job::Hold(_) => {}
322	                }
323	            }
324	            return;
325	        }
326	    };
327	    runtime.block_on(async move {
328	        let mut checker = Checker { gauges, ..Checker::default() };
329	        let mut waiting = Queue::default();
330	        let mut open = true;
331	        loop {
332	            // Every job sent so far is taken before the next request is picked, so the queues hold every request that
333	            // waits, and a change is applied before any request sent after it.
334	            if waiting.is_empty() && open {
335	                match queue.recv().await {
336	                    Some(job) => checker.take(&config, job, &mut waiting).await,
337	                    None => open = false,
338	                }
339	            }
340	            while open {
341	                match queue.try_recv() {
342	                    Ok(job) => checker.take(&config, job, &mut waiting).await,
343	                    Err(TryRecvError::Empty) => break,
344	                    Err(TryRecvError::Disconnected) => open = false,
345	                }
346	            }
347	            let Some(asked) = waiting.next() else {
348	                match open {
349	                    true => continue,
350	                    false => break,
351	                }
352	            };
353	            asked.delivery.deliver(Some(checker.answer(&config, asked.targets).await));
354	            // After the reply, so the caller never waits for the memory check or the replacement.
355	            checker.maintain(&config).await;
356	        }
357	        if let Some(backend) = checker.backend.take() {
358	            backend.shutdown().await;
359	        }
360	    });
361	}
362	
363	#[derive(Default)]
364	struct Checker {
365	    backend: Option<Backend>,
366	    /// Compiler options read once from the tsconfig for the running checker.
367	    options: Option<serde_json::Value>,
368	    restarts: u32,
369	    /// Requests the running checker has answered.
370	    served: u32,
371	    /// Why the checker cannot be used for the rest of the session.
372	    down: Option<String>,
373	    gauges: Arc<Gauges>,
374	    /// The snapshot the last request was answered from, kept for the next.
375	    live: Option<Live>,
376	    /// Files announced as changed since `live` was brought up to date.
377	    told: FxHashSet<Utf8PathBuf>,
378	}
379	
380	/// A snapshot kept between requests, and what its program read.
381	struct Live {
382	    rpc: Arc<Rpc>,
383	    /// The files its program is rooted at.
384	    roots: Vec<String>,
385	    /// When the files were compared with the disk, just before the snapshot was built or brought up to date.
386	    read_from: SystemTime,
387	    /// Every file the program read, as it was then; `None` until listed after the reply the snapshot built.
388	    stamps: Option<FxHashMap<Utf8PathBuf, Stamp>>,
389	}
390	
391	/// The warning an answer carries when files the snapshot read changed and the checker was not told.
392	fn untold_warning(files: &[Utf8PathBuf]) -> Diagnostic {
393	    let mut named: Vec<String> = files.iter().take(UNTOLD_NAMED).map(ToString::to_string).collect();
394	    if files.len() > UNTOLD_NAMED {
395	        named.push(format!("{} more", files.len() - UNTOLD_NAMED));
396	    }
397	    Diagnostic::new(
398	        DiagnosticSeverity::Warning,
399	        DiagnosticCode::SemanticBackend,
400	        format!(
401	            "the TypeScript checker was not told that {} changed; it read every file again for this answer",
402	            named.join(", ")
403	        ),
404	    )
405	    .with_help(
406	        "Whatever writes the project's files must tell the session (`update_file` or `ensure_fresh`); an edit the \
407	         checker is not told about is answered from the text it read before.",
408	    )
409	}
410	
411	impl Checker {
412	    /// Acts on a job as it arrives: starts the process, applies a change, or files a request by its priority.
413	    async fn take(&mut self, config: &OnDemandConfig, job: Job, waiting: &mut Queue<Asked>) {
414	        match job {
415	            Job::Warm => {
416	                if self.ensure(config).await.is_ok() {
417	                    self.warm(config).await;
418	                }
419	            }
420	            Job::Changed(change) => self.told(change).await,
421	            Job::Answer(asked) => {
422	                let priority = asked.priority.clone();
423	                waiting.push(asked, priority);
424	            }
425	            #[cfg(test)]
426	            Job::Hold(released) => {
427	                released.recv().ok();
428	            }
429	        }
430	    }
431	
432	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
433	        if let Some(reason) = &self.down {
434	            return Err(reason.clone());
435	        }
436	        if self.backend.as_ref().is_some_and(|backend| !backend.is_alive()) {
437	            if let Some(dead) = self.backend.take() {
438	                dead.shutdown_within(config.shutdown_wait).await;
439	            }
440	            self.options = None;
441	            self.live = None;
442	            self.told.clear();
443	            self.restarts += 1;
444	            if self.restarts > MAX_RESTARTS {
445	                return Err(self.stay_down("the checker kept crashing".to_string()));
446	            }
447	        }
448	        if self.backend.is_none() {
449	            let backend = Backend::start(&config.project_root, 1).map_err(|reason| self.stay_down(reason))?;
450	            // A checker started after a crash counts its own programs.
451	            self.served = 0;
452	            // Initialize the session and read the compiler options once; every request after builds only its program.
453	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
454	            match Rpc::prepare(&backend.client(), config.request_timeout, tsconfig).await {
455	                Ok(options) => self.options = Some(options),
456	                Err(error) => {
457	                    backend.shutdown().await;
458	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
459	                }
460	            }
461	            self.backend = Some(backend);
462	        }
463	        Ok(())
464	    }
465	
466	    /// Builds the snapshot the first request starts from (see [`OnDemand::warm_up`]) and keeps it as the live one, its
467	    /// files stamped as a request's are after its reply. A checker that already keeps a snapshot keeps it. Past the
468	    /// memory bound, the checker stops for the session, as after a reply.
469	    async fn warm(&mut self, config: &OnDemandConfig) {
470	        if self.live.is_some() {
471	            return;
472	        }
473	        let (Some(backend), Some(options)) = (self.backend.as_ref(), self.options.as_ref()) else { return };
474	        let file = config.project_root.join(WARM_FILE).to_string();
475	        let source = warm_source(&config.project_root);
476	        let started = std::time::Instant::now();
477	        let read_from = SystemTime::now();
478	        let client = backend.client();
479	        match Rpc::open_in_memory(client, config.request_timeout, options, &[(file.clone(), source)]).await {
480	            Ok(rpc) => {
481	                self.gauges.created.fetch_add(1, Ordering::Relaxed);
482	                self.live = Some(Live { rpc: Arc::new(rpc), roots: vec![file], read_from, stamps: None });
483	            }
484	            Err(error) => {
485	                tracing::debug!(%error, "the warm-up snapshot was not built; the first request builds one");
486	                return;
487	            }
488	        }
489	        let held = self.backend.as_ref().and_then(Backend::memory_mib);
490	        tracing::debug!(ms = started.elapsed().as_millis() as u64, held_mib = ?held, "the warm-up snapshot is built");
491	        if Upkeep::decide(held, config.max_rss_mib) == Upkeep::Down {
492	            self.stop_past_bound(config, held.unwrap_or_default()).await;
493	            return;
494	        }
495	        self.stamp().await;
496	    }
497	
498	    fn stay_down(&mut self, reason: String) -> String {
499	        self.down = Some(reason.clone());
500	        reason
501	    }
502	
503	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
504	        if let Err(reason) = self.ensure(config).await {
505	            return SemanticOutcome::unavailable(reason);
506	        }
507	        let Some(backend) = self.backend.as_ref() else {
508	            return SemanticOutcome::unavailable("the checker is not running");
509	        };
510	        let client = backend.client();
511	        let mut request = SemanticRequest::new(config.project_root.clone(), targets);
512	        request.tsconfig = config.tsconfig.clone();
513	        request.request_timeout = config.request_timeout;
514	        let roots = root_files(&request);
515	        if roots.is_empty() {
516	            return group_by_file(&request).0;
517	        }
518	        let answered = match self.snapshot_for(client, config.request_timeout, roots.clone()).await {
519	            Ok((rpc, warning)) => {
