426	    /// every project file takes from a package, so later requests grow the dependency layer no further). A request
427	    /// never needs this; a benchmark or a test that wants a settled session does. Returns at once for an eager
428	    /// session, one without `load_dependencies`, and before the first answer.
429	    pub fn wait_for_dependency_load(&self) {
