740	            std::fs::copy(fixtures.join(name), root.join(name)).unwrap();
741	        }
742	        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
743	        let target = |name: &str| crate::targets_of(&output).into_iter().find(|t| t.display_name == name).unwrap();
744	        let checker = OnDemand::new(OnDemandConfig::new(root.clone()));
745	        let (sender, answered) = std::sync::mpsc::channel();
